import React from 'react';

export function AngelsLogoSvg({ size = 'md', className = '' }: { size?: 'sm' | 'md' | 'lg'; className?: string }) {
    // Logonun ana sayfadaki devasa boyuta erişmesi için yükseklik değerleri maksimuma çekildi.
    // CAFEPASTE yazısının tek başına yeterli büyüklükte görünmesi için toplam SVG yüksekliğinin devasa olması gerekiyor.
    const height = size === 'lg' ? 180 : size === 'sm' ? 90 : 150;
    
    return (
        <svg 
            xmlns="http://www.w3.org/2000/svg" 
            viewBox="0 0 866 288" 
            height={height}
            className={className}
            style={{ display: 'block' }}
            aria-label="CAFEPASTE® Angels"
        >
            <image href="data:image/png;base64," width="866" height="288" />
        </svg>
    );
}